<template><view class="page"><view v-for="item in careers" :key="item.careerId" class="card" @click="open(item)"><text>{{item.careerName}}</text><text v-if="item.viewed">已查看</text></view></view></template>
<script>import{getCatalog,getRecord,userMessage}from'@/api/zycck';export default{data:()=>({recordId:'',instanceId:'',gameId:'',categoryId:'',careers:[]}),onLoad(o){Object.assign(this,{recordId:o.recordId||'',instanceId:o.instanceId||'',gameId:o.gameId||'',categoryId:o.categoryId||''});this.load()},methods:{async load(){try{const r=await getCatalog({instanceId:this.instanceId,gameId:this.gameId});const d=r.data||{};const rows=d.careers||d.items||d.questions||[];let picked=[];if(this.recordId){try{const rr=await getRecord(this.recordId);const raw=rr.data&&((rr.data.record&&rr.data.record.careerIds)||rr.data.careerIds);picked=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch(e){}}this.careers=rows.filter(x=>String(x.hasQuestion)!=='1'&&(!this.categoryId||String(x.categoryId)===String(this.categoryId))).map(x=>({...x,careerId:x.careerId||x.careerQuestionId,careerName:x.careerName||x.name||x.title})).filter(x=>!picked.some(id=>String(id)===String(x.careerId)))}catch(e){uni.showToast({title:userMessage(e,'职业列表加载失败，请重试'),icon:'none'})}},open(i){uni.navigateTo({url:`/pages/zycck/career-detail?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&categoryId=${this.categoryId}&careerId=${i.careerId}`})}}}</script>
<style scoped>.page{padding:48rpx 30rpx;background:#f5f7fb;min-height:100vh;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center}.card{display:flex;justify-content:space-between;padding:30rpx;background:#fff;border-radius:16rpx;margin:12rpx 0;color:#243b53;box-shadow:0 6rpx 18rpx rgba(31,41,55,.04)}</style>
